{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.ClickHouse/loom",
  "title": "ClickHouse Loom",
  "description": "Shared long-term memory, document search and a code index for AI agents, self-hosted on ClickHouse.",
  "version": "1.3.0",
  "websiteUrl": "https://clickhouse.github.io/loom/",
  "repository": {
    "url": "https://github.com/ClickHouse/loom",
    "source": "github"
  },
  "icons": [
    {
      "src": "https://raw.githubusercontent.com/ClickHouse/loom/main/integrations/claude-code-plugin/assets/icon.png",
      "mimeType": "image/png",
      "sizes": ["1024x1024"]
    }
  ],
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://{loom_host}/mcp",
      "variables": {
        "loom_host": {
          "description": "Host name of your Loom server, with :port when it is not 443",
          "isRequired": true,
          "placeholder": "loom.example.com"
        }
      },
      "headers": [
        {
          "name": "Authorization",
          "description": "A writer token from the dashboard (Settings, Tokens) or `loom mint-token`; leave the header out when the server signs in through the browser",
          "value": "Bearer {token}",
          "isRequired": false,
          "isSecret": true,
          "variables": {
            "token": {
              "description": "Loom writer token (JWT)",
              "isRequired": true,
              "isSecret": true
            }
          }
        }
      ]
    }
  ],
  "_meta": {
    "io.modelcontextprotocol.registry/publisher-provided": {
      "documentation": "https://clickhouse.github.io/loom/getting-started/connect-a-coding-agent/",
      "keywords": [
        "agent-memory",
        "long-term-memory",
        "ai-agents",
        "code-intelligence",
        "code-search",
        "knowledge-base",
        "document-search",
        "mcp-server",
        "clickhouse",
        "claude-code",
        "codex"
      ]
    }
  }
}

